public static class OperationalApply {
 const string P="Assets/Afrer_Seconds/05.Model/Props/B5/",E="Assets/Afrer_Seconds/05.Model/Environment/B5/";static string Repo=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static Dictionary<string,Material> mats=new Dictionary<string,Material>();static Vector3 V(JToken a)=>new Vector3((float)a[0],(float)a[1],(float)a[2]);
 static Material Mat(string key,Color c,float metal,float smooth,string texture=null,float emission=0){string path=P+"Materials/OD_"+key+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,path);}m.name="OD_"+key;m.SetColor("_BaseColor",c);m.SetFloat("_Metallic",metal);m.SetFloat("_Smoothness",smooth);if(texture!=null){var tex=AssetDatabase.LoadAssetAtPath<Texture2D>(P+"Textures/OD_"+texture+".png");if(!tex)throw new Exception("Missing texture "+texture);m.SetTexture("_BaseMap",tex);if(texture.EndsWith("_Base")){m.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>(P+"Textures/OD_"+texture.Replace("_Base","_Normal")+".png"));m.EnableKeyword("_NORMALMAP");m.SetFloat("_BumpScale",.20f);m.SetTexture("_MetallicGlossMap",AssetDatabase.LoadAssetAtPath<Texture2D>(P+"Textures/OD_"+texture.Replace("_Base","_MetalSmooth")+".png"));m.EnableKeyword("_METALLICSPECGLOSSMAP");m.SetFloat("_Smoothness",1);}if(emission>0)m.SetTexture("_EmissionMap",tex);}if(emission>0){m.EnableKeyword("_EMISSION");m.SetColor("_EmissionColor",c*emission);}if(key=="Tag")m.SetFloat("_SpecularHighlights",0);mats[m.name]=m;EditorUtility.SetDirty(m);AssetDatabase.SaveAssetIfDirty(m);return m;}
 static Material Resolve(string name){name=name.Replace(" (Instance)","");if(mats.TryGetValue(name,out var m))return m;string key=name.Substring(name.IndexOf('_')+1);if(name.StartsWith("OD_"))throw new Exception("OD material missing: "+name);if(name.StartsWith("RD_")){m=AssetDatabase.LoadAssetAtPath<Material>(P+"Materials/SF_"+key+".mat");if(m)return m;}m=AssetDatabase.LoadAssetAtPath<Material>(P+"Materials/"+name+".mat");if(m)return m;foreach(var prefix in new[]{"SF_","RD_","SC_","SR_"}){m=AssetDatabase.LoadAssetAtPath<Material>(P+"Materials/"+prefix+key+".mat");if(m)return m;}throw new Exception("Unmapped material "+name);}
 static void Record(Transform t){if(PrefabUtility.IsPartOfPrefabInstance(t)){PrefabUtility.RecordPrefabInstancePropertyModifications(t);PrefabUtility.RecordPrefabInstancePropertyModifications(t.gameObject);foreach(var r in t.GetComponents<Renderer>())PrefabUtility.RecordPrefabInstancePropertyModifications(r);}}
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||!s.path.EndsWith("Level_B5_Circular.unity"))throw new Exception("B5 Edit required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;if(root.Find("B5_Operational_Detail"))throw new Exception("Already applied; use scoped fix");var backup=Path.GetTempPath()+"AfterSeconds_OperationalApply_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".unity";if(!EditorSceneManager.SaveScene(s,backup,true))throw new Exception("Backup failed");
 foreach(var file in Directory.GetFiles(Path.Combine(Application.dataPath,"Afrer_Seconds/05.Model/Props/B5/Textures"),"OD_*.png")){var path=P+"Textures/"+Path.GetFileName(file);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var t=(TextureImporter)AssetImporter.GetAtPath(path);t.maxTextureSize=path.Contains("Tags")?4096:1024;t.mipmapEnabled=true;t.wrapMode=TextureWrapMode.Repeat;t.filterMode=FilterMode.Trilinear;t.textureCompression=TextureImporterCompression.CompressedHQ;if(path.Contains("Normal"))t.textureType=TextureImporterType.NormalMap;if(path.Contains("MetalSmooth"))t.sRGBTexture=false;t.SaveAndReimport();}
 Mat("Carton",Color.white,0,.2f,"Carton_Base");Mat("Powder",Color.white,.3f,.5f,"Powder_Base");Mat("Polymer",Color.white,.02f,.4f,"Polymer_Base");Mat("Tag",Color.white,0,.2f,"Tags");Mat("LensGreen",new Color(.09f,.72f,.3f),.1f,.80f,null,.70f);Mat("LensAmber",new Color(.90f,.36f,.025f),.1f,.8f,null,.45f);Mat("LensOff",new Color(.04f,.08f,.065f),.1f,.80f);
 foreach(var key in new[]{"Test","Food","Issue","Decon","Lift","Power","Stock"})Mat("Screen_"+key,Color.white,.05f,.43f,"Screen_"+key,.38f);
 var manifest=JObject.Parse(File.ReadAllText(Repo+"/SourceAssets/B5_OperationalDetail/models.json"));foreach(var entry in manifest){string path=((string)entry.Value["category"]=="Environment"?E:P)+entry.Key+".fbx";AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var mi=(ModelImporter)AssetImporter.GetAtPath(path);mi.importAnimation=false;mi.importCameras=false;mi.importLights=false;mi.isReadable=true;mi.importNormals=ModelImporterNormals.Import;mi.importTangents=ModelImporterTangents.CalculateMikk;foreach(var m in AssetDatabase.LoadAssetAtPath<GameObject>(path).GetComponentsInChildren<Renderer>().SelectMany(r=>r.sharedMaterials).Where(m=>m).Distinct())mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),m.name),Resolve(m.name));mi.SaveAndReimport();}
 var plan=JObject.Parse(File.ReadAllText(Repo+"/SourceAssets/B5_OperationalDetail/layout.json"));var spatial=root.Find("B5_Spatial_Refinement");var archived=new List<string>();Action<Transform> off=t=>{t.gameObject.SetActive(false);Record(t);archived.Add(t.parent.name+"/"+t.name);};
 foreach(var room in spatial.Cast<Transform>())foreach(var t in room.Cast<Transform>().ToArray()){if(!t.gameObject.activeSelf)continue;string model=Path.GetFileNameWithoutExtension(PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(t.gameObject));bool replace=room.name=="E01"&&model.StartsWith("SF_")&&!model.EndsWith("_Interior");replace|=new[]{"SF_TestGantry","SF_TestControlConsole","SF_ElectricalSwitchgear","SF_ProcessControlBay","SF_DeconShower"}.Contains(model);replace|=room.name=="E02"&&new[]{"SF_MealAssemblyIsland","SF_MealPreparation","SF_MealTransportCart"}.Contains(model);replace|=room.name=="E03"&&new[]{"SF_PPEDispenser","SF_LinenReturnCart"}.Contains(model);if(replace)off(t);}
 off(root.Find("Remaining_Domes_Art/VL/RD_VL_Hoist"));
 var group=new GameObject("B5_Operational_Detail").transform;group.SetParent(root,false);foreach(var q in plan["placements"]){string room=(string)q["room"];var parent=group.Find(room);if(!parent){parent=new GameObject(room).transform;parent.SetParent(group,false);parent.position=V(plan["rooms"][room]["position"]);}string model=(string)q["model"];string path=((string)manifest[model]["category"]=="Environment"?E:P)+model+".fbx";var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(path),parent);g.name=(string)q["id"];g.transform.localPosition=V(q["position"]);g.transform.localRotation=Quaternion.Euler(0,(float)q["yaw"],0);g.transform.localScale=Vector3.one;if(!model.EndsWith("WorkflowFloor"))foreach(var f in g.GetComponentsInChildren<MeshFilter>()){var c=f.gameObject.AddComponent<MeshCollider>();c.sharedMesh=f.sharedMesh;}foreach(var t in g.GetComponentsInChildren<Transform>())Record(t);}
 Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);var result=new{backup,models=manifest.Count,placements=plan["placements"].Count(),archived};File.WriteAllText(Repo+"/Docs/검수/2026-11-08_B5_OperationalDetail/apply.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
